<?php
if(PHP_SAPI!=='cli')exit(1);
require __DIR__.'/../.local/wordpress/wp-load.php';
$checks=[];$check=function($test,$pass)use(&$checks){$checks[]=['test'=>$test,'pass'=>(bool)$pass];echo ($pass?'PASS':'FAIL').': '.$test."\n";};
$posts=get_posts(['post_type'=>'post','post_status'=>'publish','numberposts'=>-1,'meta_key'=>'_mm_demo_article','meta_value'=>1]);
$check('Eight published editorial articles',count($posts)===8);
$words=[];$fixtures=['articles'=>[],'categories'=>[]];
foreach($posts as $post){$words[$post->post_name]=str_word_count(wp_strip_all_tags($post->post_content));$check('Complete article: '.$post->post_name,$words[$post->post_name]>=1000&&get_post_thumbnail_id($post)&&get_post_meta($post->ID,'_mm_seo_title',true)&&get_post_meta($post->ID,'_mm_meta_description',true)&&str_contains($post->post_content,'<h2>')&&!str_contains($post->post_content,'{{home}}'));$fixtures['articles'][]=['id'=>$post->ID,'slug'=>$post->post_name,'url'=>get_permalink($post),'title'=>$post->post_title,'seo_title'=>get_post_meta($post->ID,'_mm_seo_title',true),'description'=>get_post_meta($post->ID,'_mm_meta_description',true)];}
$cats=get_terms(['taxonomy'=>'category','hide_empty'=>false,'exclude'=>[(int)get_option('default_category')]]);$check('Ten native editorial categories',count($cats)===10);foreach($cats as $cat)$fixtures['categories'][]=get_term_link($cat);
$blog=get_post((int)get_option('page_for_posts'));$check('WordPress posts page assigned',$blog&&$blog->post_name==='journal');
$stock=[];foreach(wc_get_products(['limit'=>-1]) as $p)$stock[$p->get_id()]=$p->get_stock_quantity();$hashes=array_map(fn($p)=>hash('sha256',$p->post_content),$posts);$orders=wc_get_orders(['limit'=>-1,'return'=>'ids']);
mm_seed_expansion();$after=get_posts(['post_type'=>'post','post_status'=>'publish','numberposts'=>-1,'meta_key'=>'_mm_demo_article','meta_value'=>1]);$check('Reimport preserves articles and avoids duplicates',count($after)===8&&$hashes===array_map(fn($p)=>hash('sha256',$p->post_content),$after));$fresh=[];foreach(wc_get_products(['limit'=>-1]) as $p)$fresh[$p->get_id()]=$p->get_stock_quantity();$check('Reimport preserves stock and orders',$stock===$fresh&&$orders===wc_get_orders(['limit'=>-1,'return'=>'ids']));
wp_set_current_user(0);$check('Anonymous visitors cannot edit article SEO',!current_user_can('edit_post',$posts[0]->ID));wp_set_current_user(1);$check('Administrator can edit article SEO',current_user_can('edit_post',$posts[0]->ID));
$id=$posts[0]->ID;$old=get_post_meta($id,'_mm_seo_title',true);$_POST['mm_seo_nonce']=wp_create_nonce('mm_seo_save');$_POST['_mm_seo_title']='Verified editorial SEO title';wp_update_post(['ID'=>$id,'post_excerpt'=>$posts[0]->post_excerpt]);$check('Nonce-protected SEO metadata saves',get_post_meta($id,'_mm_seo_title',true)==='Verified editorial SEO title');update_post_meta($id,'_mm_seo_title',$old);unset($_POST['mm_seo_nonce'],$_POST['_mm_seo_title']);
$temp=wp_insert_post(['post_type'=>'post','post_title'=>'Disposable scheduled QA article','post_status'=>'future','post_date'=>wp_date('Y-m-d H:i:s',time()+DAY_IN_SECONDS),'post_date_gmt'=>gmdate('Y-m-d H:i:s',time()+DAY_IN_SECONDS)]);$check('Native article scheduling registers a WordPress event',get_post_status($temp)==='future'&&(bool)wp_next_scheduled('publish_future_post',[$temp]));wp_delete_post($temp,true);
$dynamic=wp_insert_post(['post_type'=>'post','post_status'=>'publish','post_title'=>'Disposable latest Journal QA article','post_content'=>'Temporary editorial publication test.']);
try{$url=get_permalink($dynamic);$response=wp_remote_get(home_url('/'),['timeout'=>30]);$check('Publishing a post automatically updates the homepage',!is_wp_error($response)&&str_contains(wp_remote_retrieve_body($response),'href="'.$url.'"'));wp_update_post(['ID'=>$dynamic,'post_status'=>'draft']);$response=wp_remote_get(home_url('/'),['timeout'=>30]);$check('Drafting a post removes it from the homepage',!is_wp_error($response)&&!str_contains(wp_remote_retrieve_body($response),'href="'.$url.'"'));}finally{wp_delete_post($dynamic,true);}
$pages=json_decode(file_get_contents(MM_CORE_DIR.'data/support-pages.json'),true);foreach($pages as $slug=>$page){$p=get_page_by_path($slug);$check('Published support page: '.$slug,$p&&$p->post_status==='publish'&&strlen($p->post_content)>100);}
$check('Original test orders remain accessible',wc_get_order(59)&&wc_get_order(67));
file_put_contents(__DIR__.'/../.local/qa-journal.json',json_encode(['checks'=>$checks,'words'=>$words],JSON_PRETTY_PRINT));file_put_contents(__DIR__.'/../.local/journal-fixtures.json',json_encode($fixtures,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
exit(count(array_filter($checks,fn($r)=>!$r['pass']))?1:0);
